      {
        "id": "SG-osaka-fork-state-transition",
        "name": "Block State Transition",
        "description": "Core state_transition function that applies a block to the chain. Validates RLP block size against MAX_RLP_BLOCK_SIZE (EIP-7934), validates the header, executes apply_body, and verifies all post-execution roots, blooms, gas used, blob gas used, and requests hash match the header commitments.",
        "invariants": [
