      {
        "id": "SG-osaka-fork-header-validation",
        "name": "Header Validation",
        "description": "validate_header checks all header fields against protocol rules: block number sequencing, timestamp ordering, gas limit bounds, base fee calculation, excess blob gas, PoS fields (difficulty=0, nonce=0, empty ommers_hash), extra_data size, and parent hash linkage.",
