      {
        "id": "SG-osaka-fork-base-fee",
        "name": "Base Fee Calculation (EIP-1559)",
        "description": "Calculates the EIP-1559 base fee per gas for a block based on parent block utilization relative to the gas target (gas_limit / ELASTICITY_MULTIPLIER). Fee adjusts up when above target, down when below, capped by BASE_FEE_MAX_CHANGE_DENOMINATOR.",
        "invariants": [
          {
            "id": "INV-osaka-fork-030",
            "text": "Gas limit must pass check_gas_limit validation against parent, or InvalidBlock is raised."
          },
          {
            "id": "INV-osaka-fork-031",
            "text": "When parent_gas_used == parent_gas_target, base fee remains unchanged."
          },
          {
            "id": "INV-osaka-fork-032",
            "text": "When parent_gas_used > parent_gas_target, base fee increases by at least 1."
          },
          {
            "id": "INV-osaka-fork-033",
            "text": "When parent_gas_used < parent_gas_target, base fee decreases (can reach 0)."
          },
          {
            "id": "INV-osaka-fork-034",
            "text": "Maximum base fee change per block is bounded by parent_base_fee / BASE_FEE_MAX_CHANGE_DENOMINATOR (= 12.5%)."
